struct stringx
{
	char data[8];
};

struct color32
{
	unsigned int value;
};

class Font
{
public:
	enum HORIZJUST
	{
		HORIZJUST_CENTER
	};
	enum VERTJUST
	{
		VERTJUST_CENTER
	};
};

class TextString
{
public:
	TextString(void *, const char *, int, int, int, float,
		Font::HORIZJUST, Font::VERTJUST, color32);
	void setButtonScale(float);
};

class FEMenuSystem;

class FEManager
{
public:
	void *font_info;
	color32 col_info_g;
	color32 col_unselected;
	color32 col_highlight;
	color32 col_highlight2;
};

class FEMenu
{
public:
	int center_x;
	int center_y;
	int num_entries;
	int dy;
	int half;
	int menu_num;
	int init;
	stringx font_filename;
	color32 color;
	color32 color_high;
	color32 color_high_alt;
	float scale;
	float scale_high;
	int max_vis_entries;
	int flags;
	void *entries;
	void *first_vis_entry;
	void *last_vis_entry;
	void *highlighted;
	FEMenuSystem *system;
	void *back;
	int back_num;
	void *submenus;
	void *active;
	void *parent;
	TextString *helpText;
	int helpFlags;
	void *next_sub;

	void SetHelpText(int);
};

class FrontEnd
{
public:
	void cons(FEManager *, stringx, stringx);
};

enum
{
	FEMENU_HAS_COLOR = 4,
	FEMENU_HAS_COLOR_HIGH = 8,
	FEMENU_HAS_COLOR_HIGH_ALT = 16,
	HF_CONTINUE = 1
};

class FEGraphicalMenu : public FEMenu, public FrontEnd
{
public:
	void cons(FEMenuSystem *, FEManager *, stringx, stringx);
};

void FEGraphicalMenu::cons(FEMenuSystem* s, FEManager* man, stringx path, stringx pf_name)
{
	entries = 0;
	highlighted = 0;
	back = 0;
	system = s;
	num_entries = 0;
	init = false;
	active = 0;
	next_sub = 0;
	parent = 0;

	// Ick.
	helpText = new TextString(&man->font_info, "", 320, 424, 20, 0.8f, Font::HORIZJUST_CENTER, Font::VERTJUST_CENTER, man->col_info_g);
	helpText->setButtonScale(1.0f);
	SetHelpText(HF_CONTINUE);

	// default values for FEMenu stuff
	center_x = 100;
	center_y = 100;
	flags = 0;
	flags |= FEMENU_HAS_COLOR;
	flags |= FEMENU_HAS_COLOR_HIGH;
	flags |= FEMENU_HAS_COLOR_HIGH_ALT;
	color = man->col_unselected;
	color_high = man->col_highlight;
	color_high_alt = man->col_highlight2;
	max_vis_entries = 1;
	scale = 1;
	scale_high = 1;
	FrontEnd::cons(man, path, pf_name);
}
